(()=>{
 const KEY='tribu-cockpit-site-import-test-v1';let found=[];let busy=false;
 const panel=document.createElement('section');panel.className='panel';panel.style='margin:24px;max-width:1100px';
 panel.innerHTML=`<h2>Importer mes biens en ligne</h2><p>Indiquez le lien de votre site ou de votre page d’annonces. Vérifiez les résultats avant de créer vos dossiers.</p><form id="site-import-form"><label for="advisor-site">Lien de mon site</label><div style="display:flex;gap:12px;flex-wrap:wrap;margin:12px 0"><input id="advisor-site" type="url" required placeholder="https://…" style="flex:1;min-width:220px;padding:12px;border:1px solid #ccd5dd;border-radius:8px"><button class="btn-add" type="submit">Rechercher mes biens</button></div></form><p>Version test : dossiers importés conservés dans ce navigateur. Les informations du vendeur sont à compléter.</p><p id="site-import-status" role="status" aria-live="polite"></p><div id="site-import-results"></div><button id="site-import-create" class="btn-add" hidden>Créer les dossiers sélectionnés</button>`;
 const home=document.getElementById('view-home');const mount=()=>{if(!home.contains(panel))home.append(panel);};
 const old=renderHome;renderHome=function(){old();mount();};mount();
 const input=panel.querySelector('input'),status=panel.querySelector('[role=status]'),results=panel.querySelector('#site-import-results'),create=panel.querySelector('#site-import-create'),search=panel.querySelector('button');
 try{const saved=JSON.parse(localStorage.getItem(KEY)||'{}');input.value=saved.site||'';for(const c of saved.clients||[])if(!clients.some(x=>x.id===c.id))clients.push(c);render();renderStats();renderHome();}catch{status.textContent='Le stockage local est indisponible ou illisible.';}
 const persist=()=>localStorage.setItem(KEY,JSON.stringify({site:input.value,clients:clients.filter(c=>c.importSource==='advisor-site')}));
 // Persist subsequent edits/deletions to imported dossiers as well.
 for(const name of ['fbUpdate','fbDelete']){const previous=window[name];if(typeof previous==='function')window[name]=async(...args)=>{const out=await previous(...args);persist();return out;};}
 panel.querySelector('form').addEventListener('submit',async e=>{
 e.preventDefault();if(busy)return;busy=true;search.disabled=true;create.hidden=true;results.replaceChildren();status.textContent='Recherche des annonces…';
 try{const r=await fetch('/api/import-site',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:input.value.trim()})});const data=await r.json();if(!r.ok)throw Error(data.error||'Import indisponible.');found=data.listings;status.textContent=data.message;
 found.forEach((item,i)=>{const row=document.createElement('label');row.style='display:flex;gap:12px;padding:14px 0;border-bottom:1px solid #dde5eb';const cb=document.createElement('input');cb.type='checkbox';cb.value=i;cb.checked=false;cb.disabled=clients.some(c=>c.sourceUrl===item.url&&c.propertyTitle===item.title);const detail=document.createElement('div');const title=document.createElement('strong');title.textContent=item.title;const p=document.createElement('p');p.textContent=[item.address,item.price?item.price.toLocaleString('fr-FR')+' €':'Prix à compléter',cb.disabled?'Déjà importé':'Vendeur à renseigner'].filter(Boolean).join(' · ');const a=document.createElement('a');a.href=item.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Vérifier l’annonce';detail.append(title,p,a);row.append(cb,detail);results.append(row);});create.hidden=!found.length;
 }catch(err){status.textContent=err.message;}finally{busy=false;search.disabled=false;}
 });
 create.addEventListener('click',async()=>{const selected=[...results.querySelectorAll('input:checked:not(:disabled)')];if(!selected.length){status.textContent='Sélectionnez au moins une annonce après vérification.';return;}create.disabled=true;
 const additions=selected.map(cb=>{const p=found[Number(cb.value)];return {id:'site-'+crypto.randomUUID(),name:'Vendeur à renseigner',addr:p.address||p.title,propertyTitle:p.title,price:p.price,step:'contact',sourceUrl:p.url,importSource:'advisor-site',notes:p.title+'\nAnnonce : '+p.url+'\n'+p.description+'\nIdentité du vendeur et mandat à compléter.'};});
 try{localStorage.setItem(KEY,JSON.stringify({site:input.value,clients:[...clients.filter(c=>c.importSource==='advisor-site'),...additions]}));clients.push(...additions);render();renderStats();renderHome();selected.forEach(cb=>{cb.checked=false;cb.disabled=true;});status.textContent=additions.length+' dossier(s) créé(s) dans le suivi vendeurs. Complétez les coordonnées et le mandat avant de préparer le LAB-FT.';}catch{status.textContent='Enregistrement impossible : vérifiez l’espace de stockage de votre navigateur.';}finally{create.disabled=false;}
 });
})();
